53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_YEARS_THRESHOLD = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	
62	// Spec price list: each item type has an insurance value and a base premium.
63	const PRICE_LIST: Record<
64	  string,
65	  { insuranceValue: number; basePremium: number }
66	> = {
67	  sword: { insuranceValue: 1000, basePremium: 100 },
68	  amulet: { insuranceValue: 600, basePremium: 60 },
69	  staff: { insuranceValue: 800, basePremium: 80 },
70	  potion: { insuranceValue: 400, basePremium: 40 },
71	  rune: { insuranceValue: 250, basePremium: 25 },
72	  moonstone: { insuranceValue: 250, basePremium: 25 },
73	};
74	
75	const sumOf = <T>(items: T[], valueOf: (item: T) => number): number =>
76	  items.reduce((sum, item) => sum + valueOf(item), 0);
77	
78	const basePremiumOf = (type: string): number => PRICE_LIST[type].basePremium;
79	
80	const insuranceValueOf = (type: string): number =>
81	  PRICE_LIST[type].insuranceValue;
82	
83	// "A building block of 3 alike components is offered at a special base premium of 60 G."
84	const COMPONENT_TYPES = ["rune", "moonstone"];
85	const BLOCK_SIZE = 3;
86	const COMPONENT_BLOCK_PREMIUM = 60;
87	
88	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
89	
90	const isLoyalCustomer = (customer: Customer): boolean =>
91	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
92	
93	const isHighlyEnchanted = (item: QuoteItem): boolean =>
94	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
95	
96	// Surcharges apply per item, as a percentage of that item's base premium.
97	const surchargeOn = (
98	  items: QuoteItem[],
99	  applies: (item: QuoteItem) => boolean,
100	  rate: number,
101	): number =>
102	  sumOf(items, (item) =>
103	    applies(item) ? basePremiumOf(item.type) * rate : 0,
104	  );
105	
106	const quotePremium = (
107	  items: QuoteItem[],
108	  customer: Customer,
109	  isFollowUpContract: boolean,
110	): number => {
111	  const itemBase = sumOf(items, (item) => basePremiumOf(item.type));
112	  const blockDiscount = sumOf(COMPONENT_TYPES, (type) => {
113	    const count = items.filter((item) => item.type === type).length;
114	    return count === BLOCK_SIZE
115	      ? BLOCK_SIZE * basePremiumOf(type) - COMPONENT_BLOCK_PREMIUM
116	      : 0;
117	  });
118	  const policyBase = itemBase - blockDiscount;
119	  const curseSurcharge = surchargeOn(items, isCursed, CURSE_SURCHARGE_RATE);
120	  const highEnchantmentSurcharge = surchargeOn(
121	    items,
122	    isHighlyEnchanted,
123	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
124	  );
125	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
126	  const loyaltyDiscount = isLoyalCustomer(customer)
127	    ? policyBase * LOYALTY_DISCOUNT_RATE
128	    : 0;
129	  const followUpDiscount = isFollowUpContract
130	    ? policyBase * FOLLOW_UP_DISCOUNT_RATE
131	    : 0;
132	  return Math.ceil(
133	    policyBase +
134	      curseSurcharge +
135	      highEnchantmentSurcharge +
136	      firstInsurance -
137	      loyaltyDiscount -
138	      followUpDiscount +
139	      PROCESSING_FEE,
140	  );
141	};
142	
143	const DEDUCTIBLE = 100;
144	const CAP_MULTIPLIER = 2;
145	// "Items with an enchantment level of 8 or higher are reimbursed at 50%."
146	const CLAIM_ENCHANTMENT_THRESHOLD = 8;
147	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
148	
149	const reimbursementFor = (
150	  damage: Damage,
151	  insuredItem: QuoteItem | undefined,
152	): number =>
153	  (insuredItem?.enchantment ?? 0) >= CLAIM_ENCHANTMENT_THRESHOLD
154	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
155	    : damage.amount;
156	
157	const policyCap = (policy: QuoteStep): number =>
158	  CAP_MULTIPLIER *
159	  sumOf(policy.items, (item) => insuranceValueOf(item.type));
160	
161	const settleClaim = (
162	  claim: ClaimStep,
163	  policy: QuoteStep,
164	  remainingCapBefore: number,
165	): ClaimResult => {
166	  const rawPayout = sumOf(claim.incident.damages, (damage) => {
167	    const insuredItem = policy.items.find(
168	      (item) => item.type === damage.itemType,
169	    );
170	    return reimbursementFor(damage, insuredItem) - DEDUCTIBLE;
171	  });
172	  const payout = Math.min(Math.floor(rawPayout), remainingCapBefore);
173	  return { payout, remainingCap: remainingCapBefore - payout };
174	};
175	
176	export const runScenario = (scenario: Scenario): ScenarioOutput => {
177	  const remainingCaps = new Map<number, number>();
178	  const results = scenario.steps.map((step, index): StepResult => {
179	    if (step.op === "claim") {
180	      const policy = scenario.steps[step.policy] as QuoteStep;
181	      const remainingCapBefore =
182	        remainingCaps.get(step.policy) ?? policyCap(policy);
183	      const result = settleClaim(step, policy, remainingCapBefore);
184	      remainingCaps.set(step.policy, result.remainingCap);
185	      return result;
186	    }
187	    const isFollowUpContract = index > 0;
188	    return {
189	      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
190	    };
191	  });
192	  return { results };
193	};
